700→func displayRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
701→	sort.SliceStable(sessions, func(i, j int) bool {
702→		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
703→	})
704→
705→	if len(sessions) > 1 {
706→		fmt.Fprintf(w, "\n✓ Restored %d sessions. To continue, run:\n", len(sessions))
707→	} else if len(sessions) == 1 {
708→		fmt.Fprintf(w, "✓ Restored session %s.\n", sessions[0].SessionID)
709→		fmt.Fprintf(w, "\nTo continue this session, run:\n")
710→	}
711→
712→	isMulti := len(sessions) > 1
713→	for i, sess := range sessions {
714→		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
715→		if err != nil {
716→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
717→		}
718→		printSessionCommand(w, sessionAgent.FormatResumeCommand(sess.SessionID), sess.Prompt, isMulti, i == len(sessions)-1)
719→	}
720→
721→	return nil
722→}
723→
724→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
725→// Always overwrites existing session logs to ensure consistency with checkpoint state.
726→// If force is false, prompts for confirmation when local log has newer timestamps.
727→func resumeSingleSession(ctx context.Context, w, errW io.Writer, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
728→	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
729→	if err != nil {
730→		return fmt.Errorf("failed to resolve transcript path: %w", err)
731→	}
732→
733→	if checkpointID.IsEmpty() {
734→		logging.Debug(ctx, "resume session: empty checkpoint ID",
735→			slog.String("checkpoint_id", checkpointID.String()),
736→		)
737→		fmt.Fprintf(w, "Session '%s' found in commit trailer but session log not available\n", sessionID)
738→		fmt.Fprintf(w, "\nTo continue this session, run:\n")
739→		fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
740→		return nil
741→	}
742→
743→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
744→	if err != nil {
745→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
746→			logging.Debug(ctx, "resume session completed (no metadata)",
747→				slog.String("checkpoint_id", checkpointID.String()),
748→				slog.String("session_id", sessionID),
749→			)
750→			fmt.Fprintf(w, "Session '%s' found in commit trailer but session log not available\n", sessionID)
751→			fmt.Fprintf(w, "\nTo continue this session, run:\n")
752→			fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
753→			return nil
754→		}
755→		logging.Error(ctx, "resume session failed",
756→			slog.String("checkpoint_id", checkpointID.String()),
757→			slog.String("session_id", sessionID),
758→			slog.String("error", err.Error()),
759→		)
760→		return fmt.Errorf("failed to get session log: %w", err)
761→	}
762→
763→	// Check if local file has newer timestamps than checkpoint
764→	if !force {
765→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
766→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
767→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
768→
