 68→// setupResumeTestRepo creates a test repository with an initial commit and optional feature branch.
 69→// Returns the repository, worktree, and commit hash. The caller should use t.Chdir(tmpDir).
 70→func setupResumeTestRepo(t *testing.T, tmpDir string, createFeatureBranch bool) (*git.Repository, *git.Worktree, plumbing.Hash) {
 71→	t.Helper()
 72→
 73→	repo, err := git.PlainInit(tmpDir, false)
 74→	if err != nil {
 75→		t.Fatalf("Failed to init repo: %v", err)
 76→	}
 77→
 78→	w, err := repo.Worktree()
 79→	if err != nil {
 80→		t.Fatalf("Failed to get worktree: %v", err)
 81→	}
 82→
 83→	testFile := filepath.Join(tmpDir, "test.txt")
 84→	if err := os.WriteFile(testFile, []byte("test content"), 0o644); err != nil {
 85→		t.Fatalf("Failed to write test file: %v", err)
 86→	}
 87→	if _, err := w.Add("test.txt"); err != nil {
 88→		t.Fatalf("Failed to add test file: %v", err)
 89→	}
 90→
 91→	commit, err := w.Commit("initial commit", &git.CommitOptions{
 92→		Author: &object.Signature{
 93→			Name:  "Test User",
 94→			Email: "test@example.com",
 95→		},
 96→	})
 97→	if err != nil {
 98→		t.Fatalf("Failed to create initial commit: %v", err)
 99→	}
100→
101→	if createFeatureBranch {
102→		featureRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("feature"), commit)
103→		if err := repo.Storer.SetReference(featureRef); err != nil {
104→			t.Fatalf("Failed to create feature branch: %v", err)
105→		}
106→	}
107→
108→	// Ensure entire/checkpoints/v1 branch exists
109→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
110→		t.Fatalf("Failed to create metadata branch: %v", err)
111→	}
112→
113→	return repo, w, commit
114→}
