292→// createCheckpointOnMetadataBranchFull creates a checkpoint on the entire/checkpoints/v1 branch
293→// with a caller-specified checkpoint ID and timestamp.
294→func createCheckpointOnMetadataBranchFull(t *testing.T, repo *git.Repository, sessionID string, checkpointID id.CheckpointID, createdAt time.Time) id.CheckpointID {
295→	t.Helper()
296→
297→	// Get existing metadata branch or create it
298→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
299→		t.Fatalf("Failed to ensure metadata branch: %v", err)
300→	}
301→
302→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
303→	ref, err := repo.Reference(refName, true)
304→	if err != nil {
305→		t.Fatalf("Failed to get metadata branch ref: %v", err)
306→	}
307→
308→	parentCommit, err := repo.CommitObject(ref.Hash())
309→	if err != nil {
310→		t.Fatalf("Failed to get parent commit: %v", err)
311→	}
312→
313→	// Create metadata content
314→	metadataJSON := fmt.Sprintf(`{
315→  "checkpoint_id": %q,
316→  "session_id": %q,
317→  "created_at": %q
318→}`, checkpointID.String(), sessionID, createdAt.Format(time.RFC3339))
319→
320→	// Create blob for metadata
321→	blob := repo.Storer.NewEncodedObject()
322→	blob.SetType(plumbing.BlobObject)
323→	writer, err := blob.Writer()
324→	if err != nil {
325→		t.Fatalf("Failed to create blob writer: %v", err)
326→	}
327→	if _, err := writer.Write([]byte(metadataJSON)); err != nil {
328→		t.Fatalf("Failed to write blob: %v", err)
329→	}
330→	if err := writer.Close(); err != nil {
331→		t.Fatalf("Failed to close writer: %v", err)
332→	}
333→	metadataBlobHash, err := repo.Storer.SetEncodedObject(blob)
334→	if err != nil {
335→		t.Fatalf("Failed to store blob: %v", err)
336→	}
337→
338→	// Create session log blob
339→	logBlob := repo.Storer.NewEncodedObject()
340→	logBlob.SetType(plumbing.BlobObject)
341→	logWriter, err := logBlob.Writer()
342→	if err != nil {
343→		t.Fatalf("Failed to create log blob writer: %v", err)
344→	}
345→	if _, err := logWriter.Write([]byte(`{"type":"test"}`)); err != nil {
346→		t.Fatalf("Failed to write log blob: %v", err)
347→	}
348→	if err := logWriter.Close(); err != nil {
349→		t.Fatalf("Failed to close log writer: %v", err)
350→	}
351→	logBlobHash, err := repo.Storer.SetEncodedObject(logBlob)
352→	if err != nil {
353→		t.Fatalf("Failed to store log blob: %v", err)
354→	}
355→
356→	// Build tree structure: <id[:2]>/<id[2:]>/metadata.json
357→	shardedPath := checkpointID.Path()
358→	checkpointIDStr := checkpointID.String()
359→
360→	// Create checkpoint tree with metadata and transcript files
361→	// Entries must be sorted alphabetically
362→	checkpointTree := object.Tree{
363→		Entries: []object.TreeEntry{
364→			{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
365→			{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataBlobHash},
366→		},
367→	}
368→	checkpointTreeObj := repo.Storer.NewEncodedObject()
369→	if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
370→		t.Fatalf("Failed to encode checkpoint tree: %v", err)
371→	}
372→	checkpointTreeHash, err := repo.Storer.SetEncodedObject(checkpointTreeObj)
373→	if err != nil {
374→		t.Fatalf("Failed to store checkpoint tree: %v", err)
375→	}
376→
377→	// Create inner shard tree (id[2:])
378→	innerTree := object.Tree{
379→		Entries: []object.TreeEntry{
380→			{Name: checkpointIDStr[2:], Mode: filemode.Dir, Hash: checkpointTreeHash},
381→		},
382→	}
383→	innerTreeObj := repo.Storer.NewEncodedObject()
384→	if err := innerTree.Encode(innerTreeObj); err != nil {
385→		t.Fatalf("Failed to encode inner tree: %v", err)
386→	}
387→	innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
388→	if err != nil {
389→		t.Fatalf("Failed to store inner tree: %v", err)
390→	}
391→
392→	// Get existing tree entries from parent
393→	parentTree, err := parentCommit.Tree()
394→	if err != nil {
395→		t.Fatalf("Failed to get parent tree: %v", err)
396→	}
397→
398→	// Build new root tree with shard bucket
399→	var rootEntries []object.TreeEntry
400→	for _, entry := range parentTree.Entries {
401→		if entry.Name != shardedPath[:2] {
402→			rootEntries = append(rootEntries, entry)
403→		}
404→	}
405→	rootEntries = append(rootEntries, object.TreeEntry{
406→		Name: checkpointIDStr[:2],
407→		Mode: filemode.Dir,
408→		Hash: innerTreeHash,
409→	})
410→
411→	rootTree := object.Tree{Entries: rootEntries}
412→	rootTreeObj := repo.Storer.NewEncodedObject()
413→	if err := rootTree.Encode(rootTreeObj); err != nil {
414→		t.Fatalf("Failed to encode root tree: %v", err)
415→	}
416→	rootTreeHash, err := repo.Storer.SetEncodedObject(rootTreeObj)
417→	if err != nil {
418→		t.Fatalf("Failed to store root tree: %v", err)
419→	}
420→
421→	// Create commit on metadata branch
422→	commit := &object.Commit{
423→		Author: object.Signature{
424→			Name:  "Test",
425→			Email: "test@example.com",
426→			When:  parentCommit.Author.When,
427→		},
428→		Committer: object.Signature{
429→			Name:  "Test",
430→			Email: "test@example.com",
431→			When:  parentCommit.Author.When,
432→		},
433→		Message:      "Add checkpoint metadata",
434→		TreeHash:     rootTreeHash,
435→		ParentHashes: []plumbing.Hash{parentCommit.Hash},
436→	}
437→	commitObj := repo.Storer.NewEncodedObject()
438→	if err := commit.Encode(commitObj); err != nil {
439→		t.Fatalf("Failed to encode commit: %v", err)
440→	}
441→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
442→	if err != nil {
443→		t.Fatalf("Failed to store commit: %v", err)
444→	}
445→
446→	// Update metadata branch ref
447→	newRef := plumbing.NewHashReference(refName, commitHash)
448→	if err := repo.Storer.SetReference(newRef); err != nil {
449→		t.Fatalf("Failed to update metadata branch: %v", err)
450→	}
451→
452→	return checkpointID
453→}
