455→// TestResolveLatestCheckpoint verifies that resolveLatestCheckpoint returns the
456→// checkpoint with the newest CreatedAt, regardless of trailer order.
457→func TestResolveLatestCheckpoint(t *testing.T) {
458→	tmpDir := t.TempDir()
459→	t.Chdir(tmpDir)
460→
461→	repo, _, _ := setupResumeTestRepo(t, tmpDir, false)
462→
463→	// Create checkpoints with different timestamps.
464→	// Simulate git CLI squash merge order: newest first in the commit message.
465→	t1 := time.Date(2025, 1, 1, 10, 0, 0, 0, time.UTC) // oldest
466→	t2 := time.Date(2025, 1, 1, 11, 0, 0, 0, time.UTC)
467→	t3 := time.Date(2025, 1, 1, 12, 0, 0, 0, time.UTC) // newest
468→
469→	cpID1 := createCheckpointOnMetadataBranchFull(t, repo, "session-oldest", id.MustCheckpointID("aaa111bbb222"), t1)
470→	cpID2 := createCheckpointOnMetadataBranchFull(t, repo, "session-middle", id.MustCheckpointID("ccc333ddd444"), t2)
471→	cpID3 := createCheckpointOnMetadataBranchFull(t, repo, "session-newest", id.MustCheckpointID("eee555fff666"), t3)
472→
473→	// Pass checkpoint IDs in reverse chronological order (newest first),
474→	// simulating git CLI squash merge trailer order.
475→	reverseOrderIDs := []id.CheckpointID{cpID3, cpID2, cpID1}
476→	latest, tree, _, err := resolveLatestCheckpoint(context.Background(), reverseOrderIDs)
477→	if err != nil {
478→		t.Fatalf("resolveLatestCheckpoint() error = %v", err)
479→	}
480→
481→	// Should return the newest checkpoint regardless of input order
482→	if latest.String() != cpID3.String() {
483→		t.Errorf("resolveLatestCheckpoint() = %s, want newest %s", latest, cpID3)
484→	}
485→
486→	// Should return a non-nil tree for reuse
487→	if tree == nil {
488→		t.Error("resolveLatestCheckpoint() returned nil tree")
489→	}
490→
491→	// Also verify with chronological order
492→	chronologicalIDs := []id.CheckpointID{cpID1, cpID2, cpID3}
493→	latest2, _, _, err := resolveLatestCheckpoint(context.Background(), chronologicalIDs)
494→	if err != nil {
495→		t.Fatalf("resolveLatestCheckpoint() error = %v", err)
496→	}
497→	if latest2.String() != cpID3.String() {
498→		t.Errorf("resolveLatestCheckpoint() = %s, want newest %s", latest2, cpID3)
499→	}
500→}
