190→	if len(shortID) > 7 {
191→		shortID = shortID[:7]
192→	}
193→
194→	// Show what was selected
195→	switch {
196→	case selectedPoint.IsLogsOnly:
197→		// Committed checkpoint - show sha
198→		fmt.Fprintf(w, "\nSelected: %s %s\n", shortID, sanitizeForTerminal(selectedPoint.Message))
199→	case selectedPoint.IsTaskCheckpoint:
200→		// Task checkpoint - no sha
201→		fmt.Fprintf(w, "\nSelected: [Task] %s\n", sanitizeForTerminal(selectedPoint.Message))
202→	default:
203→		// Shadow checkpoint - no sha
204→		fmt.Fprintf(w, "\nSelected: %s\n", sanitizeForTerminal(selectedPoint.Message))
205→	}
206→
207→	// Handle logs-only points with a sub-choice menu
208→	if selectedPoint.IsLogsOnly {
209→		return handleLogsOnlyRewindInteractive(ctx, w, errW, start, *selectedPoint, shortID)
210→	}
211→
212→	// Preview rewind to show warnings about files that will be deleted
213→	preview, previewErr := start.PreviewRewind(ctx, *selectedPoint)
214→	if previewErr != nil {
215→		fmt.Fprintf(errW, "Warning: could not preview rewind effects: %v\n", previewErr)
216→	} else if preview != nil && len(preview.FilesToDelete) > 0 {
217→		fmt.Fprintf(errW, "\nWarning: The following untracked files will be DELETED:\n")
218→		for _, f := range preview.FilesToDelete {
219→			fmt.Fprintf(errW, "  - %s\n", f)
220→		}
221→		fmt.Fprintf(errW, "\n")
222→	}
223→
224→	// Confirm rewind
225→	var confirm bool
226→	description := fmt.Sprintf("This will reset to: %s\nChanges after this point may be lost!", selectedPoint.Message)
227→	confirmForm := NewAccessibleForm(
228→		huh.NewGroup(
229→			huh.NewConfirm().
230→				Title(fmt.Sprintf("Reset to %s?", shortID)).
231→				Description(description).
232→				Value(&confirm),
233→		),
234→	)
235→
236→	if err := confirmForm.Run(); err != nil {
237→		if errors.Is(err, huh.ErrUserAborted) {
238→			return nil
239→		}
240→		return fmt.Errorf("confirmation failed: %w", err)
241→	}
242→
243→	if !confirm {
244→		fmt.Fprintln(w, "Rewind cancelled.")
245→		return nil
246→	}
247→
248→	// Resolve agent once for use throughout
249→	agent, err := getAgent(selectedPoint.Agent)
250→	if err != nil {
251→		return fmt.Errorf("failed to get agent: %w", err)
252→	}
253→
254→	// Initialize logging context with agent from checkpoint
255→	logCtx := logging.WithComponent(ctx, "rewind")
256→	logCtx = logging.WithAgent(logCtx, agent.Name())
257→
258→	logging.Debug(logCtx, "rewind started",
259→		slog.String("checkpoint_id", selectedPoint.ID),
260→		slog.String("session_id", selectedPoint.SessionID),
261→		slog.Bool("is_task_checkpoint", selectedPoint.IsTaskCheckpoint),
262→	)
263→
264→	// Perform the rewind using strategy
265→	if err := start.Rewind(ctx, w, errW, *selectedPoint); err != nil {
266→		logging.Error(logCtx, "rewind failed",
267→			slog.String("checkpoint_id", selectedPoint.ID),
268→			slog.String("error", err.Error()),
269→		)
270→		return err //nolint:wrapcheck // already present in codebase
271→	}
272→
273→	logging.Debug(logCtx, "rewind completed",
274→		slog.String("checkpoint_id", selectedPoint.ID),
275→	)
276→
277→	// Handle transcript restoration differently for task checkpoints
278→	var sessionID string
279→	var transcriptFile string
280→
281→	if selectedPoint.IsTaskCheckpoint {
282→		// For task checkpoint: read checkpoint.json to get UUID and truncate transcript
283→		checkpoint, err := start.GetTaskCheckpoint(ctx, *selectedPoint)
284→		if err != nil {
285→			fmt.Fprintf(errW, "Warning: failed to read task checkpoint: %v\n", err)
286→			return nil
287→		}
288→
289→		sessionID = checkpoint.SessionID
290→
291→		if checkpoint.CheckpointUUID != "" {
292→			// Truncate transcript at checkpoint UUID
293→			if err := restoreTaskCheckpointTranscript(ctx, w, start, *selectedPoint, sessionID, checkpoint.CheckpointUUID, agent); err != nil {
294→				fmt.Fprintf(errW, "Warning: failed to restore truncated session transcript: %v\n", err)
295→			} else {
296→				fmt.Fprintf(w, "✓ Rewound to task checkpoint. %s\n", agent.FormatResumeCommand(sessionID))
297→			}
298→			return nil
299→		}
300→	} else {
301→		// For session checkpoint: restore full transcript
302→		// Prefer SessionID from trailer (set by GetRewindPoints from Entire-Session trailer)
303→		// over path-based extraction which is less reliable.
304→		sessionID = selectedPoint.SessionID
305→		if sessionID == "" {
306→			sessionID = filepath.Base(selectedPoint.MetadataDir)
307→		}
308→		transcriptFile = filepath.Join(selectedPoint.MetadataDir, paths.TranscriptFileNameLegacy)
309→	}
310→
311→	// Try to restore transcript using the appropriate method:
312→	// 1. Checkpoint storage (committed checkpoints with valid checkpoint ID)
313→	// 2. Shadow branch (uncommitted checkpoints with commit hash)
314→	// 3. Local file (active sessions)
315→	var restored bool
316→	if !selectedPoint.CheckpointID.IsEmpty() {
317→		// Try checkpoint storage first for committed checkpoints
318→		if returnedSessionID, err := restoreSessionTranscriptFromStrategy(ctx, selectedPoint.CheckpointID, sessionID, agent); err == nil {
319→			sessionID = returnedSessionID
320→			restored = true
321→		}
322→	}
323→
324→	if !restored && selectedPoint.MetadataDir != "" && len(selectedPoint.ID) == 40 {
325→		// Try shadow branch for uncommitted checkpoints (ID is a 40-char commit hash)
326→		if returnedSessionID, err := restoreSessionTranscriptFromShadow(ctx, selectedPoint.ID, selectedPoint.MetadataDir, sessionID, agent); err == nil {
327→			sessionID = returnedSessionID
328→			restored = true
329→		}
330→	}
331→
332→	if !restored {
333→		// Fall back to local file
334→		if err := restoreSessionTranscript(ctx, w, transcriptFile, sessionID, agent); err != nil {
335→			fmt.Fprintf(errW, "Warning: failed to restore session transcript: %v\n", err)
336→			fmt.Fprintf(errW, "  Source: %s\n", transcriptFile)
337→			fmt.Fprintf(errW, "  Session ID: %s\n", sessionID)
338→		}
339→	}
340→
341→	fmt.Fprintf(w, "✓ Rewound to %s. %s\n", shortID, agent.FormatResumeCommand(sessionID))
342→	return nil
343→}
